use vstd::prelude::*;

verus! {

fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        result@ == a@,
        result@.len() == a@.len(),
{
    let mut result = Vec::with_capacity(a.len());
    for &item in a.iter()
        invariant
            result@ == a@.subrange(0, result@.len() as int),
            result@.len() <= a@.len(),
    {
        result.push(item);
    }
    result
}

} // verus!

